(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[138],{1477:function(n,t,e){"use strict";e.r(t),t.default={code:"114TCPE17",title:"114-金門縣國小（競賽模式）",unlockCode:"114TCPE17",tasks:[{id:"114TCPE17-1",code:"114TCPE17-114TCPE17-1",title:"1-資訊競賽獎勵統計",description:"縣府舉辦「科技教育創意實作競賽」，共有許多選手參加。評審委員們根據每位選手的最終得分(0至100分)，頒發不同等級的獎勵。由於參賽人數眾多，請寫一個程式協助主辦單位統計獲得「金牌獎」、「銀牌獎」與「銅牌獎」的人數各有多少。\n每位選手的得分僅會被歸類在最高的一項獎勵中(不可重複領獎)：\n1. 金牌獎：若得分為90分(含)以上。\n2. 銀牌獎：若不符合金牌獎，但得分為80分(含)以上。\n3. 銅牌獎：若不符合上述獎項，但得分為70分(含)以上。\n4. 佳作：若不符合上述獎項，但得分為60分(含)以上。\n5. 參賽證明：若得分未滿60分，則僅頒發參賽證明，不計入上述獎項。\n【輸入說明】\n• 第一行輸入一個整數N，代表總參賽人數。\n• 接下來輸入N行，每行包含一個整數，代表該名選手的得分。\n【輸出說明】\n• 輸出四個整數，分別代表獲得「金牌獎」、「銀牌獎」、「銅牌獎」與「佳作」的總張數，中間以逗號隔開。",examples:[{input:"6\n92\n55\n80\n90\n72\n65",output:"2,1,1,1",explanation:"總共6位選手：\n92, 90分：金牌獎(2人)\n80分：銀牌獎(1人)\n72分：銅牌獎(1人)\n65分：佳作(1人)\n55分：未達標，不計入獎項"},{input:"3\n45\n60\n59",output:"0,0,0,1",explanation:"總共3位選手：\n60分符合「佳作」(1人)\n45, 59分皆未滿60分。"}],testCases:[{input:"6\n92\n55\n80\n90\n72\n65",expectedOutput:"2,1,1,1",score:10},{input:"3\n45\n60\n59",expectedOutput:"0,0,0,1",score:10},{input:"5\n100\n100\n100\n100\n100",expectedOutput:"5,0,0,0",score:10},{input:"4\n85\n88\n80\n89",expectedOutput:"0,4,0,0",score:10},{input:"3\n75\n70\n79",expectedOutput:"0,0,3,0",score:10},{input:"2\n60\n69",expectedOutput:"0,0,0,2",score:10},{input:"5\n0\n10\n20\n30\n40",expectedOutput:"0,0,0,0",score:10},{input:"8\n95\n85\n75\n65\n55\n45\n99\n81",expectedOutput:"2,2,1,1",score:10},{input:"1\n90",expectedOutput:"1,0,0,0",score:10},{input:"10\n60\n60\n70\n70\n80\n80\n90\n90\n50",expectedOutput:"2,2,2,2",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE17-2",code:"114TCPE17-114TCPE17-2",title:"2-台灣星鏈(T-Starlink) 衛星佈署計畫",description:"台灣正致力於研發自主低軌衛星通訊系統「T-Starlink」，以確保在特殊情況下通訊不中斷。TASA 國家太空中心預計在特定的軌道高度上，沿著預定路徑佈署通訊衛星。根據衛星的訊號覆蓋半徑與任務需求，不同路徑段有不同的佈署模式。請寫一個程式，根據路徑總長度、衛星間的固定間隔，以及指定的「佈署模式」，計算該路段總共需要佈署多少顆衛星。\n衛星佈署分為兩種模式：\n• 模式1(全線佈署)：從起點開始放，每隔一段距離放一顆，且路徑的「終點」也必須放一顆。\n• 模式2(銜接佈署)：從起點開始放，每隔一段距離放一顆，但路徑的「終點」不放衛星(留給下一個路段使用)。\n【輸入說明】\n1. 第一行輸入一個整數L，代表路段長度(公里)。\n2. 第二行輸入一個整數D，代表衛星間的固定間隔(公里)。\n3. 第三行輸入一個整數M，代表模式(1或2)。\n(備註：為了簡化計算，本題保證L必定能被D整除)\n【輸出說明】\n• 輸出一個整數，代表所需的衛星總數。",examples:[{input:"1000\n200\n1",output:"6",explanation:"長度 1000公里，每200公里放一顆。間隔有5個，因為模式 1終點也要放，所以是5+1=6"},{input:"1000\n250\n2",output:"4",explanation:"長度1000公里，每250公里放一顆。間隔有4個，因為模式2 終點不放，所以總共就是4顆"}],testCases:[{input:"1000\n200\n1",expectedOutput:"6",score:10},{input:"1000\n250\n2",expectedOutput:"4",score:10},{input:"500\n100\n1",expectedOutput:"6",score:10},{input:"500\n100\n2",expectedOutput:"5",score:10},{input:"2000\n500\n1",expectedOutput:"5",score:10},{input:"2000\n500\n2",expectedOutput:"4",score:10},{input:"100\n10\n1",expectedOutput:"11",score:10},{input:"100\n10\n2",expectedOutput:"10",score:10},{input:"300\n300\n1",expectedOutput:"2",score:10},{input:"300\n300\n2",expectedOutput:"1",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE17-3",code:"114TCPE17-114TCPE17-3",title:"3-「一杯心情」飲料調製",description:"金門最近開了一間超人氣手搖店「一杯心情」，調飲師會依照顧客的心情，製作一杯具有層次感的「心情飲料」：現在要製作的是一杯「四層漸層奶蓋茶」。為了讓飲料呈現漂亮的分層效果，店長規定原料必須依照「密度(重量)」的大小順序依次倒入杯中，密度大的原料會沉在下層，密度小的原料會浮在上層。\n請你模擬調飲師倒入原料的過程，根據輸入的原料資料，輸出完成後飲料「由下往上」的正確層次順序。\n【原料代碼表】\n• B：黑糖糖漿(Brown Sugar)\n• M：鮮奶(Milk)\n• T：茶(Tea)\n• F：奶蓋(Foam)\n【調製規則】\n• 每種原料皆有一個整數密度值 D\n• 調飲師會先倒入密度最大的原料，再依序倒入密度較小的原料\n• 原料倒入後不可重新調整位置\n• 這四種原料的密度值保證皆不相同\n【輸入說明】\n• 共有4組資料\n• 每組包含：一個大寫字母(B, M, T, F)\n• 一個整數(代表密度D)\n（註：格式以逗號隔開如範例所示）\n【輸出說明】\n• 請輸出4個原料代碼\n• 代表飲料完成後，由杯底到杯口的原料排列順序\n• 每個代碼之間以一個逗號隔開",examples:[{input:"B,130\nM,110\nT,120\nF,95",output:"B,T,M,F",explanation:"密度比較：B(130) > T(120) > M(110) > F(95)\n最重的B放底部，接著往上是T、M，最輕的F在最上面。"},{input:"F,100\nB,140\nM,125\nT,115",output:"B,M,T,F",explanation:"密度比較：B(140) > M(125) > T(115) > F(100)\n順序為 B,M,T,F"}],testCases:[{input:"B,130\nM,110\nT,120\nF,95",expectedOutput:"B,T,M,F",score:10},{input:"F,100\nB,140\nM,125\nT,115",expectedOutput:"B,M,T,F",score:10},{input:"B,10\nM,20\nT,30\nF,40",expectedOutput:"F,T,M,B",score:10},{input:"M,50\nB,40\nT,60\nF,30",expectedOutput:"T,M,B,F",score:10},{input:"B,100\nM,200\nT,300\nF,400",expectedOutput:"F,T,M,B",score:10},{input:"T,1\nM,2\nB,3\nF,4",expectedOutput:"F,B,M,T",score:10},{input:"B,99\nM,98\nT,97\nF,96",expectedOutput:"B,M,T,F",score:10},{input:"F,50\nM,40\nT,30\nB,20",expectedOutput:"F,M,T,B",score:10},{input:"B,111\nM,222\nT,333\nF,444",expectedOutput:"F,T,M,B",score:10},{input:"M,10\nT,20\nF,30\nB,40",expectedOutput:"B,F,T,M",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE17-4",code:"114TCPE17-114TCPE17-4",title:"4-數位交趾陶花",description:"金門的交趾陶產業正結合科技藝術，開發一款「數位交趾陶花預覽器」。這款程式使用 Scratch 的「畫筆」內的「蓋章」功能來設計花朵圖案。只要將同一個花瓣圖形依照固定角度重複旋轉並蓋章，就可以畫出一朵對稱又漂亮的花。\n請你依照下列規則，根據輸入的花瓣數量N，畫出對應的花朵圖形。\n【繪圖規則說明】\n1. 選擇角色 Button2一開始位於舞台正中央\n2. 角色初始面向為0度\n3. 點選花瓣造型，花瓣需離開畫布中心一段距離\n4. 每畫出一片花瓣，需依序執行以下兩個動作：\n• 使用畫筆「蓋章一次」\n• 原地向右旋轉固定角度\n5. 總共需要畫出 N 片花瓣\n6. 每次旋轉的角度為 360 ÷ N 度\n7. 不需要考慮花瓣的顏色、大小或形狀，只需依規則完成蓋章動作\n【輸入說明】\n• 輸入一個正整數 N\n• 表示花朵的花瓣數量\n【輸出說明】\n(圖形輸出)\n• 請使用 Scratch 的畫筆功能\n• 畫出完成後的花朵圖形\n• 花瓣必須平均分布，形成一個完整的圓形",examples:[{input:"8",output:"8片對稱花瓣",explanation:"每次旋轉角度為360÷8=45度\n共蓋章8次\n形成8片對稱花瓣"},{input:"12",output:"12片對稱花瓣",explanation:"每次旋轉角度為360÷12=30度\n共蓋章 12 次\n形成 12片對稱花瓣"}],testCases:[{input:"8",expectedOutput:"8片對稱花瓣",score:10},{input:"12",expectedOutput:"12片對稱花瓣",score:10},{input:"4",expectedOutput:"4片對稱花瓣",score:10},{input:"5",expectedOutput:"5片對稱花瓣",score:10},{input:"6",expectedOutput:"6片對稱花瓣",score:10},{input:"10",expectedOutput:"10片對稱花瓣",score:10},{input:"15",expectedOutput:"15片對稱花瓣",score:10},{input:"20",expectedOutput:"20片對稱花瓣",score:10},{input:"36",expectedOutput:"36片對稱花瓣",score:10},{input:"72",expectedOutput:"72片對稱花瓣",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE17-5",code:"114TCPE17-114TCPE17-5",title:"5-風獅爺排排隊",description:"金門各村落的風獅爺要準備祭典大合照，村長要求將4尊風獅爺依照身高「由矮到高」排好。工讀生小金負責進行搬動，規則如下：\n• 比較規則：從小金的角度看，每次比較相鄰的兩尊風獅爺。\n• 交換規則：如果「左邊」的風獅爺比「右邊」的高，兩尊就必須交換位置。\n• 紀錄規則：每當風獅爺成功交換一次位置，小金就要在筆記本上畫一個「正」字(紀錄總交換次數)。\n請寫一個程式，幫小金算出排好隊後的風獅爺身高，以及他總共搬動(交換)了幾次。\n【任務說明】\n1. 將輸入的4個身高數值，由小到大排列。\n2. 計算在排序過程中，總共執行了幾次「交換」動作。(使用氣泡排序法邏輯)\n【輸入說明】\n• 每行輸入1個整數，代表1個風獅爺的身高。\n【輸出說明】\n• 輸出由矮到高排列後的4個身高數值，中間以空白隔開。\n• 和前面的結果以逗號隔開，輸出一個整數，代表「總共交換的次數」。(如範例：`100 110 120 150,6`)",examples:[{input:"150\n120\n110\n100",output:"100 110 120 150,6",explanation:"這是「最麻煩」的情況(全倒過來排)。\n150 要一路換到最後，接著120再換，總共會交換 6 次。"},{input:"120\n110\n140\n130",output:"110 120 130 140,2",explanation:"120與110換一次；140與130換一次，總共2次"}],testCases:[{input:"150\n120\n110\n100",expectedOutput:"100 110 120 150,6",score:10},{input:"120\n110\n140\n130",expectedOutput:"110 120 130 140,2",score:10},{input:"10\n20\n30\n40",expectedOutput:"10 20 30 40,0",score:10},{input:"40\n30\n20\n10",expectedOutput:"10 20 30 40,6",score:10},{input:"20\n10\n40\n30",expectedOutput:"10 20 30 40,2",score:10},{input:"30\n10\n20\n40",expectedOutput:"10 20 30 40,2",score:10},{input:"40\n10\n20\n30",expectedOutput:"10 20 30 40,3",score:10},{input:"20\n30\n40\n10",expectedOutput:"10 20 30 40,3",score:10},{input:"30\n40\n10\n20",expectedOutput:"10 20 30 40,4",score:10},{input:"10\n40\n20\n30",expectedOutput:"10 20 30 40,2",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPE17-6",code:"114TCPE17-114TCPE17-6",title:"7-智慧掃地機器人",description:"小金家買了一台智慧掃地機器人，這台機器人只能依照固定規則在室內移動，並且會一直沿著牆壁前進，避免撞到家具。現在請你幫忙設計程式，控制掃地機器人依照「靠右走」的規則，從起點出發，走到「電池充電處」。\n【環境說明】\n1. 俯視圖是由許多正方形格子組成，每一格大小相同，都是20單位。\n2. 機器人一次只能移動到「前方相鄰的一格」。\n3. 圖中的牆壁不可穿越。\n4. 只有一個「電池充電處」。\n5. 保證使用正確的「靠右走規則」一定可以走到「電池充電處」。\n【機器人初始狀態】\n• 起始位置：由題目提供的迷宮圖標示\n• 起始方向：面向「90度」\n• 初始步數：0步\n【移動規則(靠右走)】\n機器人每一步必須依照以下順序判斷並執行：\n1. 右邊有路可以走 → 直接前進一格\n2. 右邊沒有路，但下方有路 → 先向右轉，再前進一格\n3. 右邊與前方都沒有路，但左邊有路 → 向左轉，再前進一格\n4. 右、前、左都沒有路 → 向後轉(轉 180度)，再前進一格\n*每一次移動，只能執行其中一個規則。\n【任務說明】\n請設計一個程式，控制掃地機器人：\n• 從起點開始移動\n• 依照「靠右走」規則前進\n• 直到到達「電池充電處」為止\n【輸入說明】\n本題不需要由使用者輸入資料。迷宮圖、起點與電池位置將於測試時提供。\n【輸出說明】\n• 程式結束時，請一併輸出機器人到達「電池充電處」時的總步數",examples:[{input:"(無輸入)",output:"依實際迷宮步數而定",explanation:"本題為 Scratch 迷宮模擬實作題，無一般文字輸入。"}],testCases:[{input:"1",expectedOutput:"依實際迷宮步數而定",score:10},{input:"2",expectedOutput:"依實際迷宮步數而定",score:10},{input:"3",expectedOutput:"依實際迷宮步數而定",score:10},{input:"4",expectedOutput:"依實際迷宮步數而定",score:10},{input:"5",expectedOutput:"依實際迷宮步數而定",score:10},{input:"6",expectedOutput:"依實際迷宮步數而定",score:10},{input:"7",expectedOutput:"依實際迷宮步數而定",score:10},{input:"8",expectedOutput:"依實際迷宮步數而定",score:10},{input:"9",expectedOutput:"依實際迷宮步數而定",score:10},{input:"10",expectedOutput:"依實際迷宮步數而定",score:10}],difficulty:"L2",sb3Path:null}]}}}]);